"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion } from "framer-motion";
import * as Dialog from "@radix-ui/react-dialog";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { Activity, ArrowDown, ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, BookOpen, CalendarDays, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, Download, Ellipsis, ExternalLink, FileCheck2, FileClock, FilePlus2, FileText, Filter, Globe2, LayoutDashboard, Link2, ListFilter, Loader2, LogOut, Mail, Menu, MessageSquare, Moon, Paperclip, Plus, Search, Send, Settings2, ShieldCheck, Sparkles, Sun, Trash2, TrendingUp, Upload, Users, Wind, X, Zap } from "lucide-react";
import { Button } from "./ui/button";
import { RichEditor } from "./rich-editor";
import { canSend, checklistLabels, minuteSchema, minutesSeed, nextVersion, parksSeed, people, safeUrl, sectionLabels, stripHtml, type Attachment, type Minute, type MinuteFields, type Park, type Role, type Status } from "@/lib/domain";
import { exportPdf } from "@/lib/pdf";
import { useSharedWorkspace } from "@/lib/shared-workspace";
import { CloudAccess } from "./cloud-access";

type View = "dashboard" | "minutes" | "parks" | "team" | "reports" | "integrations" | "settings";
const names: Record<View, string> = { dashboard: "Visão geral", minutes: "Atas semanais", parks: "Parques eólicos", team: "Equipe", reports: "Relatórios", integrations: "Integrações", settings: "Configurações" };
const navItems = [{ id: "dashboard" as View, icon: LayoutDashboard }, { id: "minutes" as View, icon: FileText }, { id: "parks" as View, icon: Wind }, { id: "team" as View, icon: Users }, { id: "reports" as View, icon: Activity }];
const formatDate = (date: string) => new Date(date.length === 10 ? `${date}T12:00:00` : date).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" }).replace(" de ", " ").replace(".", "");
const shortPark = (name: string) => name.replace("Complexo Eólico ", "").replace("Parque Eólico ", "");

function Modal({ open, onClose, title, subtitle, children, wide = false }: { open: boolean; onClose: () => void; title: string; subtitle?: string; children: ReactNode; wide?: boolean }) {
  return <Dialog.Root open={open} onOpenChange={state => { if (!state) onClose(); }}><Dialog.Portal><Dialog.Overlay className="modal-overlay" /><Dialog.Content className={`modal ${wide ? "modal-wide" : ""}`} aria-describedby={subtitle ? "modal-description" : undefined}><div className="modal-heading"><div><Dialog.Title>{title}</Dialog.Title>{subtitle && <Dialog.Description id="modal-description">{subtitle}</Dialog.Description>}</div><Dialog.Close asChild><Button variant="ghost" size="icon" aria-label="Fechar"><X size={20} /></Button></Dialog.Close></div>{children}</Dialog.Content></Dialog.Portal></Dialog.Root>;
}
function Avatar({ name, small = false }: { name: string; small?: boolean }) {
  const person = people.find(item => item.name === name);
  return <span className={`avatar ${person?.color ?? "teal"} ${small ? "avatar-small" : ""}`}>{person?.initials ?? name.split(" ").map(word => word[0]).slice(0, 2).join("")}</span>;
}
function Badge({ status }: { status: Status }) { return <span className={`badge ${status === "Enviada" ? "badge-green" : status === "Pendente" ? "badge-amber" : "badge-gray"}`}><span />{status}</span>; }

export function Workspace({ onLock }: { onLock?: () => void } = {}) {
  const shared = useSharedWorkspace();
  const { minutes, setMinutes, parks, setParks, publicAccess } = shared;
  const [view, setView] = useState<View>("dashboard");
  const [ready, setReady] = useState(false);
  const [dark, setDark] = useState(false);
  const [sidebar, setSidebar] = useState(false);
  const [query, setQuery] = useState("");
  const [region, setRegion] = useState("all");
  const [period, setPeriod] = useState("month");
  const [parkFilter, setParkFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [dispatcherFilter, setDispatcherFilter] = useState("all");
  const [weekFilter, setWeekFilter] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [advanced, setAdvanced] = useState(false);
  const [page, setPage] = useState(0);
  const [editor, setEditor] = useState<Minute | "new" | null>(null);
  const [viewOnly, setViewOnly] = useState(false);
  const [emailMinute, setEmailMinute] = useState<Minute | null>(null);
  const [recipients, setRecipients] = useState("");
  const [emailError, setEmailError] = useState("");
  const [parkEditor, setParkEditor] = useState<Park | "new" | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ kind: "minute" | "park"; id: string } | null>(null);
  const [notification, setNotification] = useState(false);
  const [toast, setToast] = useState("");
  const [demoRole, setRole] = useState<Role>("Administrador");
  const role: Role = publicAccess ? (shared.isAdmin && shared.ready && !shared.error ? "Administrador" : "Leitor") : demoRole;
  const [help, setHelp] = useState(false);
  const [integration, setIntegration] = useState<string | null>(null);
  const [settingsSaved, setSettingsSaved] = useState(false);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const notify = (message: string) => { setToast(message); if (toastTimer.current) clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(""), 5000); };
  useEffect(() => {
    try { const saved = localStorage.getItem("wind-planner-v1"); if (saved) setDark(Boolean(JSON.parse(saved).dark)); } catch { setToast("Não foi possível restaurar o tema."); }
    setReady(true);
  }, []);
  useEffect(() => { if (ready) { document.documentElement.classList.toggle("dark", dark); try { const saved = JSON.parse(localStorage.getItem("wind-planner-v1") ?? "{}"); localStorage.setItem("wind-planner-v1", JSON.stringify({ ...saved, dark })); } catch { setToast("Não foi possível salvar o tema."); } } }, [dark, ready]);
  useEffect(() => { setPage(0); }, [query, region, parkFilter, statusFilter, dispatcherFilter, weekFilter, dateFrom, dateTo, period]);
  const navigate = (next: View) => { setView(next); setSidebar(false); setQuery(""); setPage(0); };
  const editable = role !== "Leitor";
  const scoped = minutes.filter(minute => {
    const park = parks.find(item => item.id === minute.parkId);
    const text = `${park?.name} ${minute.dispatcher} ${minute.week} ${minute.territory}`.toLocaleLowerCase("pt-BR");
    return (!query || text.includes(query.toLocaleLowerCase("pt-BR"))) && (region === "all" || park?.region === region) && (period !== "week" || minute.week === 44) && (period !== "last" || minute.week === 43) && (parkFilter === "all" || minute.parkId === parkFilter) && (statusFilter === "all" || minute.status === statusFilter) && (dispatcherFilter === "all" || minute.dispatcher === dispatcherFilter) && (!weekFilter || minute.week === Number(weekFilter)) && (!dateFrom || minute.date >= dateFrom) && (!dateTo || minute.date <= dateTo);
  });
  const sent = scoped.filter(minute => minute.status === "Enviada").length;
  const pending = scoped.filter(minute => minute.status === "Pendente").length;
  const drafts = scoped.filter(minute => minute.status === "Rascunho").length;
  const openNew = () => { setViewOnly(false); setEditor("new"); };
  const saveMinute = (minute: Minute) => { setMinutes(previous => previous.some(item => item.id === minute.id) ? previous.map(item => item.id === minute.id ? minute : item) : [minute, ...previous]); setEditor(null); notify(publicAccess ? "Alteração registrada. Aguarde a confirmação de publicação no painel da nuvem." : "Ata salva. Histórico de versão atualizado."); };
  const duplicate = (minute: Minute) => { const copy: Minute = { ...minute, id: crypto.randomUUID(), status: "Rascunho", version: 1, date: new Date().toISOString().slice(0, 10), sentAt: undefined, audit: [{ version: 1, actor: "Ana Martins", date: new Date().toISOString(), action: `Duplicada de ${minute.id}` }] }; setMinutes(previous => [copy, ...previous]); setViewOnly(false); setEditor(copy); };
  const requestEmail = (minute: Minute) => { if (!canSend(minute)) { notify("Complete os 13 itens do checklist, os participantes e o conteúdo antes de enviar."); setViewOnly(false); setEditor(minute); return; } setRecipients(""); setEmailError(""); setEmailMinute(minute); };
  const sendDemo = () => {
    const emails = recipients.split(/[;,]/).map(value => value.trim()).filter(Boolean);
    if (!emails.length || emails.some(value => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))) { setEmailError("Informe ao menos um e-mail válido, separado por vírgula."); return; }
    if (emailMinute) { const updated = nextVersion({ ...emailMinute, status: "Enviada", sentAt: new Date().toISOString() }, "Ana Martins", `Envio simulado para ${emails.join(", ")}`); setMinutes(previous => previous.map(item => item.id === updated.id ? updated : item)); setEmailMinute(null); notify("Envio simulado registrado. Nenhum e-mail real foi enviado."); }
  };
  const table = (compact = false) => <div className="table-scroll"><table><thead><tr><th>PARQUE / ATA</th><th>SEMANA</th><th>DISPATCHER</th><th>DATA DA REUNIÃO</th><th>STATUS</th><th className="text-right">AÇÕES</th></tr></thead><tbody>{scoped.slice(compact ? 0 : page * 8, compact ? 5 : page * 8 + 8).map(minute => {
    const park = parks.find(item => item.id === minute.parkId);
    return <tr key={minute.id}><td><button className="table-title" onClick={() => { setViewOnly(true); setEditor(minute); }}><span className="file-tile"><FileText size={19} /></span><span>{shortPark(park?.name ?? "Parque removido")}<small>{park?.state} <span className="middot">·</span> {park?.client}</small></span></button></td><td><span className="week-label">S{minute.week}</span><small className="under-text">2026</small></td><td><div className="person-cell"><Avatar name={minute.dispatcher} small /><span>{minute.dispatcher}</span></div></td><td className="muted">{formatDate(minute.date)}, 2026</td><td><Badge status={minute.status} /></td><td><div className="row-actions"><Button variant="ghost" size="icon" title="Baixar PDF" aria-label={`Baixar PDF ${shortPark(park?.name ?? "")}`} onClick={() => void exportPdf(minute, park).catch(() => notify("Não foi possível gerar o PDF."))}><Download size={16} /></Button><details className="actions-menu"><summary aria-label="Mais ações"><Ellipsis size={19} /></summary><div className="dropdown"><button onClick={() => { setViewOnly(true); setEditor(minute); }}><FileText size={15} />Visualizar ata</button>{editable && <><button onClick={() => { setViewOnly(false); setEditor(minute); }}><FilePlus2 size={15} />Editar ata</button><button onClick={() => duplicate(minute)}><Copy size={15} />Duplicar</button><button onClick={() => requestEmail(minute)}><Send size={15} />{minute.status === "Enviada" ? "Reenviar e-mail" : "Enviar ata"}</button></>}{role === "Administrador" && <button className="danger-text" onClick={() => setDeleteTarget({ kind: "minute", id: minute.id })}><Trash2 size={15} />Excluir ata</button>}</div></details></div></td></tr>;
  })}</tbody></table>{!scoped.length && <div className="empty-state"><Search size={30} /><h3>Nenhuma ata encontrada</h3><p>Altere os filtros ou crie uma nova ata.</p><Button variant="outline" onClick={() => { setQuery(""); setRegion("all"); setParkFilter("all"); setStatusFilter("all"); setDispatcherFilter("all"); setWeekFilter(""); setDateFrom(""); setDateTo(""); setPeriod("month"); }}>Limpar filtros</Button></div>}</div>;

  return <div className={`app-shell ${publicAccess ? "public-mode" : ""}`}>
    {sidebar && <div className="sidebar-backdrop" onClick={() => setSidebar(false)} />}
    <aside className={`sidebar ${sidebar ? "sidebar-open" : ""}`}>
      <a className="brand" href="#" onClick={event => { event.preventDefault(); navigate("dashboard"); }}><span className="brand-mark"><Wind size={27} strokeWidth={2} /></span><span>wind<span className="brand-light">planner</span><small>OPERATION IN SYNC</small></span></a>
      <button className="workspace-switch" onClick={() => setHelp(true)}><span className="workspace-symbol">V</span><span>Vestas Brasil<small>Service Operations</small></span><ChevronDown size={15} /></button>
      <div className="nav-caption">WORKSPACE</div>
      <nav aria-label="Navegação principal">{navItems.map(({ id, icon: Icon }) => <button key={id} onClick={() => navigate(id)} className={`nav-item ${view === id ? "active" : ""}`}><Icon size={19} /><span>{names[id]}</span>{id === "minutes" && <span className="nav-count">{minutes.length}</span>}{view === id && <span className="active-indicator" />}</button>)}</nav>
      <div className="nav-divider" /><div className="nav-caption">GERENCIAMENTO</div>
      <nav aria-label="Gerenciamento"><button className={`nav-item ${view === "integrations" ? "active" : ""}`} onClick={() => navigate("integrations")}><Zap size={19} /><span>Integrações</span><span className="tiny-dot" /></button><button className={`nav-item ${view === "settings" ? "active" : ""}`} onClick={() => navigate("settings")}><Settings2 size={19} /><span>Configurações</span></button></nav>
      <div className="sidebar-bottom"><div className="help-box"><span className="help-symbol"><Wind size={22} /></span><h4>Planejamento que move.</h4><p>Uma operação mais conectada começa aqui.</p><button onClick={() => setHelp(true)}>Central de ajuda <ArrowUpRight size={15} /></button></div><div className="sidebar-status"><span className="status-dot" /> Ambiente de demonstração <CircleHelp size={13} /></div><div className="sidebar-footer"><span className="vestas-wordmark">Vestas</span><span>Wind Planner v1.0</span></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="topbar-left"><Button className="mobile-toggle" variant="ghost" size="icon" onClick={() => setSidebar(true)} aria-label="Abrir menu"><Menu size={21} /></Button><span className="breadcrumb">Workspace <ChevronRight size={13} /> <strong>{names[view]}</strong></span></div><div className="topbar-right"><div className="global-search"><Search size={16} /><input placeholder="Buscar no workspace..." aria-label="Buscar no workspace" value={query} onChange={event => { setQuery(event.target.value); if (view !== "minutes" && view !== "dashboard" && view !== "parks") setView("minutes"); }} /><kbd>⌘ K</kbd></div><Button variant="ghost" size="icon" aria-label={dark ? "Ativar tema claro" : "Ativar tema escuro"} title="Alternar tema" onClick={() => setDark(!dark)}>{dark ? <Sun size={18} /> : <Moon size={18} />}</Button><div className="notification-wrap"><Button variant="ghost" size="icon" aria-label="Notificações" onClick={() => setNotification(!notification)}><Bell size={19} /><span className="notification-dot" /></Button>{notification && <div className="notification-panel"><h4>Central de notificações</h4><p><FileClock size={17} />{minutes.filter(minute => minute.status === "Pendente").length} atas aguardando envio</p><p><ShieldCheck size={17} />Seus dados estão neste navegador</p><button onClick={() => { navigate("minutes"); setStatusFilter("Pendente"); setNotification(false); }}>Ver atas pendentes <ArrowRight size={14} /></button></div>}</div><div className="topbar-divider" /><button className="profile" onClick={() => navigate("settings")}><Avatar name="Ana Martins" /><span>Ana Martins<small>{role}</small></span><ChevronDown size={14} /></button></div></header>
    <main>
      {onLock && <div className="access-session-row"><Button variant="ghost" size="sm" disabled={shared.saving} onClick={onLock}><LogOut size={14} />Sair</Button></div>}
      <CloudAccess workspace={shared} />
      <AnimatePresence mode="wait"><motion.div key={view} initial={{ opacity: 0, y: 7 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.2 }}>
      <div className="page-heading"><div><div className="eyebrow"><span /> SERVICE OPERATIONS · BRASIL</div><h1>{view === "dashboard" ? "Cada semana, uma direção." : names[view]}</h1><p>{view === "dashboard" ? "Seu planejamento conectado. Sua operação em movimento." : view === "minutes" ? "Um só lugar para planejar, registrar e compartilhar." : view === "parks" ? "Conheça os parques que movem a nossa operação." : view === "team" ? "Pessoas conectadas por uma operação mais eficiente." : view === "reports" ? "Transforme o histórico de planejamento em decisões." : view === "integrations" ? "Conecte seu planejamento ao ecossistema Microsoft e Azure." : "Preferências do workspace e segurança da operação."}</p></div><div className="heading-actions">{(view === "dashboard" || view === "minutes") && <><span className="today"><CalendarDays size={15} />29 out, 2026</span>{editable && <Button onClick={openNew}><Plus size={17} />Nova ata</Button>}</>}{view === "parks" && role === "Administrador" && <Button onClick={() => setParkEditor("new")}><Plus size={17} />Novo parque</Button>}</div></div>

      {(view === "dashboard" || view === "reports") && <>
      <div className="filter-bar"><div className="filter-bar-left"><span className="filter-icon"><ListFilter size={17} /></span><select aria-label="Filtrar por região" value={region} onChange={event => setRegion(event.target.value)}><option value="all">Todas as regiões</option><option>Nordeste</option><option>Sul</option></select><span className="filter-divider" /><select aria-label="Filtrar por parque" value={parkFilter} onChange={event => setParkFilter(event.target.value)}><option value="all">Todos os parques</option>{parks.map(park => <option key={park.id} value={park.id}>{shortPark(park.name)}</option>)}</select></div><div className="period-control"><CalendarDays size={15} /><select aria-label="Período" value={period} onChange={event => setPeriod(event.target.value)}><option value="month">Este mês</option><option value="week">Esta semana</option><option value="last">Semana anterior</option><option value="all">Todo o histórico</option></select><span className="period-date">01 out – 31 out, 2026</span></div></div>
      <div className="kpi-grid">{[
        { label: "Total de atas", value: scoped.length, icon: FileText, class: "blue", subtitle: "atas registradas no período", data: [14, 19, 17, 26, 24, 34, scoped.length], change: "+16,7%", positive: true },
        { label: "Atas enviadas", value: sent, icon: FileCheck2, class: "teal", subtitle: "planejamento compartilhado", data: [8, 15, 12, 22, 20, 29, sent], change: "+12,5%", positive: true },
        { label: "Aguardando envio", value: pending, icon: FileClock, class: "amber", subtitle: "prontas para o próximo passo", data: [10, 8, 9, 6, 7, 4, pending], change: "−25,0%", positive: true },
        { label: "Em elaboração", value: drafts, icon: FilePlus2, class: "purple", subtitle: "rascunhos em andamento", data: [3, 5, 2, 4, 2, 4, drafts], change: "Sem variação", positive: false }
      ].map((item, index) => <motion.div className="kpi-card" key={item.label} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * 0.05 }}><div className="kpi-top"><span>{item.label}</span><span className={`kpi-icon ${item.class}`}><item.icon size={19} /></span></div><div className="kpi-middle"><strong>{String(item.value).padStart(2, "0")}</strong><div className={`sparkline sparkline-${item.class}`}><ResponsiveContainer width="100%" height="100%"><AreaChart data={item.data.map((value, position) => ({ value, position }))}><defs><linearGradient id={`spark-${item.class}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity={0.16} /><stop offset="100%" stopColor="currentColor" stopOpacity={0} /></linearGradient></defs><Area dataKey="value" type="monotone" stroke="currentColor" strokeWidth={1.8} fill={`url(#spark-${item.class})`} isAnimationActive={false} /></AreaChart></ResponsiveContainer></div></div><div className="kpi-bottom"><span className={item.positive ? "trend-positive" : "trend-neutral"}>{item.positive ? <TrendingUp size={12} /> : <span>—</span>}{item.change}</span><span>vs. período anterior*</span></div></motion.div>)}</div>
      <div className="analytics-grid"><section className="panel trend-panel"><div className="panel-heading"><div><h2>Evolução das atas <span className="info-icon" title="Quantidade de atas por semana no histórico filtrado">i</span></h2><p>O ritmo do seu planejamento, semana a semana.</p></div><div className="chart-legend"><span><i className="legend-dot blue-bg" />Criadas</span><span><i className="legend-dot teal-bg" />Enviadas</span></div></div><div className="main-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={[40, 41, 42, 43, 44].map(week => ({ week: `Sem ${week}`, criadas: scoped.filter(minute => minute.week === week).length, enviadas: scoped.filter(minute => minute.week === week && minute.status === "Enviada").length }))} margin={{ left: -24, right: 12, top: 16, bottom: 0 }}><defs><linearGradient id="areaBlue" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#00a3e0" stopOpacity={0.14} /><stop offset="100%" stopColor="#00a3e0" stopOpacity={0} /></linearGradient><linearGradient id="areaTeal" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#16a790" stopOpacity={0.09} /><stop offset="100%" stopColor="#16a790" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="4 5" vertical={false} stroke="var(--chart-grid)" /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#8794a5" }} dy={10} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 11, fill: "#8794a5" }} allowDecimals={false} /><Tooltip contentStyle={{ background: "var(--surface)", border: "1px solid var(--border)", borderRadius: 8, fontSize: 12 }} /><Area name="Criadas" type="monotone" dataKey="criadas" stroke="#00a3e0" strokeWidth={2.5} fill="url(#areaBlue)" dot={{ r: 3, strokeWidth: 2, fill: "var(--surface)" }} /><Area name="Enviadas" type="monotone" dataKey="enviadas" stroke="#18a58e" strokeWidth={2.5} fill="url(#areaTeal)" dot={{ r: 3, strokeWidth: 2, fill: "var(--surface)" }} /></AreaChart></ResponsiveContainer></div><div className="chart-footer"><span><span className="status-dot" />{scoped.length ? Math.round(sent / scoped.length * 100) : 0}% das atas já foram compartilhadas</span><span>Semanas 40 – 44</span></div></section>
      <section className="panel park-chart-panel"><div className="panel-heading"><div><h2>Atas por parque</h2><p>Planejamento em cada operação.</p></div><button className="icon-plain" aria-label="Ver todos os parques" onClick={() => navigate("parks")}><ArrowUpRight size={18} /></button></div><div className="park-bars">{parks.slice(0, 5).map((park, index) => { const count = scoped.filter(minute => minute.parkId === park.id).length; const max = Math.max(...parks.map(item => scoped.filter(minute => minute.parkId === item.id).length), 1); return <button className="park-bar-item" key={park.id} onClick={() => { navigate("minutes"); setParkFilter(park.id); }}><span className="park-bar-label"><span>{shortPark(park.name)}</span><strong>{String(count).padStart(2, "0")}</strong></span><span className="park-bar-track"><span style={{ width: `${count / max * 100}%`, background: ["#00a3e0", "#37b6e2", "#64c8e8", "#90d7ec", "#b3e4f0"][index] }} /></span></button>; })}</div><button className="panel-link" onClick={() => navigate("parks")}>Explorar todos os parques <ArrowRight size={14} /></button></section></div>
      {view === "reports" && <div className="analytics-grid"><section className="panel"><div className="panel-heading"><div><h2>Atas por dispatcher</h2><p>Distribuição da programação entre responsáveis.</p></div></div><div className="main-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={people.slice(1, 4).map(person => ({ name: person.name.split(" ")[0], atas: scoped.filter(minute => minute.dispatcher === person.name).length }))}><CartesianGrid vertical={false} stroke="var(--border)" /><XAxis dataKey="name" /><YAxis allowDecimals={false} /><Tooltip /><Bar dataKey="atas" name="Atas" fill="#00a3e0" radius={[4, 4, 0, 0]} maxBarSize={54} /></BarChart></ResponsiveContainer></div></section><section className="panel"><div className="panel-heading"><div><h2>Distribuição por região</h2><p>Presença do planejamento no Brasil.</p></div></div><div className="main-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={["Nordeste", "Sul"].map(name => ({ name, value: scoped.filter(minute => parks.find(park => park.id === minute.parkId)?.region === name).length }))} dataKey="value" innerRadius={55} outerRadius={82} paddingAngle={4} label={({ name, value }) => `${name}: ${value}`}><Cell fill="#00a3e0" /><Cell fill="#18a58e" /></Pie><Tooltip /></PieChart></ResponsiveContainer></div></section></div>}
      </>}

      {(view === "dashboard" || view === "minutes") && <section className="panel minutes-panel"><div className="panel-heading"><div><h2>{view === "dashboard" ? "Atas recentes" : "Todas as atas"}<span className="count-label">{scoped.length}</span></h2><p>{view === "dashboard" ? "Os últimos registros da sua operação." : "Histórico completo e rastreável das reuniões semanais."}</p></div>{view === "dashboard" ? <Button variant="outline" size="sm" onClick={() => navigate("minutes")}>Ver todas as atas <ArrowRight size={14} /></Button> : <Button variant="outline" size="sm" onClick={() => setAdvanced(!advanced)}><Filter size={15} />Filtros {advanced ? <ChevronDown size={14} /> : null}</Button>}</div>
        {view === "minutes" && <><div className="table-filters"><div className="local-search"><Search size={16} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por parque, semana ou dispatcher..." aria-label="Buscar atas" /></div><select aria-label="Status da ata" value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="all">Todos os status</option><option>Enviada</option><option>Pendente</option><option>Rascunho</option></select><select aria-label="Parque da ata" value={parkFilter} onChange={event => setParkFilter(event.target.value)}><option value="all">Todos os parques</option>{parks.map(park => <option key={park.id} value={park.id}>{shortPark(park.name)}</option>)}</select></div>{advanced && <div className="advanced-filters"><label>Dispatcher<select value={dispatcherFilter} onChange={event => setDispatcherFilter(event.target.value)}><option value="all">Todos</option>{people.slice(1, 4).map(person => <option key={person.name}>{person.name}</option>)}</select></label><label>Região<select value={region} onChange={event => setRegion(event.target.value)}><option value="all">Todas</option><option>Nordeste</option><option>Sul</option></select></label><label>Semana<input type="number" min="1" max="53" value={weekFilter} onChange={event => setWeekFilter(event.target.value)} /></label><label>De<input type="date" value={dateFrom} onChange={event => setDateFrom(event.target.value)} /></label><label>Até<input type="date" value={dateTo} onChange={event => setDateTo(event.target.value)} /></label></div>}</>}
        {table(view === "dashboard")}<div className="table-footer"><span>{view === "dashboard" ? `Exibindo ${Math.min(5, scoped.length)} de ${scoped.length} atas` : `${scoped.length ? page * 8 + 1 : 0}–${Math.min((page + 1) * 8, scoped.length)} de ${scoped.length} atas`}</span>{view === "dashboard" ? <span className="table-sync"><span className="status-dot" />Dados demonstrativos</span> : <div className="pagination"><Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)} aria-label="Página anterior"><ChevronLeft size={16} /></Button><span>{page + 1} / {Math.max(1, Math.ceil(scoped.length / 8))}</span><Button variant="outline" size="icon" disabled={(page + 1) * 8 >= scoped.length} onClick={() => setPage(page + 1)} aria-label="Próxima página"><ChevronRight size={16} /></Button></div>}</div></section>}

      {view === "dashboard" && <div className="dashboard-bottom"><section className="operation-banner"><div className="banner-shade" /><div className="banner-copy"><span className="banner-eyebrow"><span /> CONECTADOS PELO VENTO</span><h2>Um padrão. Um processo.<br />Uma operação mais forte.</h2><p>Do planejamento à execução, movemos o futuro juntos.</p><button onClick={() => navigate("parks")}>Conheça nossa operação <ArrowUpRight size={16} /></button></div><div className="banner-stat"><Wind size={22} /><strong>{parks.length}</strong><span>parques conectados</span></div></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>Últimos envios</h2><p>Planejamento que chega à equipe.</p></div><span className="live-label"><span className="status-dot" />Histórico</span></div><div className="activity-list">{minutes.filter(minute => minute.sentAt).slice(0, 3).map(minute => <button key={minute.id} onClick={() => { setViewOnly(true); setEditor(minute); }}><span className="activity-icon"><CheckCheck size={16} /></span><span><strong>{shortPark(parks.find(park => park.id === minute.parkId)?.name ?? "Parque")}</strong><small>{minute.dispatcher.split(" ")[0]} · Semana {minute.week}</small></span><time>{formatDate(minute.sentAt!)}</time></button>)}</div></section></div>}

      {view === "parks" && <><div className="section-summary"><span><Wind size={17} />{parks.length} parques na operação</span><span><Zap size={17} />{parks.reduce((total, park) => total + park.capacity, 0).toLocaleString("pt-BR")} MW instalados</span><div className="local-search"><Search size={16} /><input placeholder="Buscar parque ou cliente..." aria-label="Buscar parques" value={query} onChange={event => setQuery(event.target.value)} /></div></div><div className="parks-grid">{parks.filter(park => `${park.name} ${park.client}`.toLowerCase().includes(query.toLowerCase())).map((park, index) => <article className="park-card" key={park.id}><div className={`park-image park-image-${index % 3}`}><span><span className="status-dot" />Em operação</span><span>{park.state}</span></div><div className="park-card-body"><span className="eyebrow">{park.region.toUpperCase()} · {park.client.toUpperCase()}</span><h2>{shortPark(park.name)}</h2><div className="park-metrics"><div><strong>{park.capacity}<small>MW</small></strong><span>Capacidade instalada</span></div><div><strong>{park.turbines}</strong><span>Aerogeradores</span></div></div><div className="park-manager"><Avatar name={park.manager} small /><div><strong>{park.manager}</strong><span>Gestor responsável</span></div></div><div className="park-card-footer"><button onClick={() => { navigate("minutes"); setParkFilter(park.id); }}>Consultar atas <ArrowRight size={14} /></button>{role === "Administrador" && <div><Button variant="ghost" size="icon" title="Editar parque" aria-label={`Editar ${shortPark(park.name)}`} onClick={() => setParkEditor(park)}><Settings2 size={16} /></Button><Button variant="ghost" size="icon" title="Excluir parque" aria-label={`Excluir ${shortPark(park.name)}`} onClick={() => setDeleteTarget({ kind: "park", id: park.id })}><Trash2 size={15} /></Button></div>}</div></div></article>)}</div></>}

      {view === "team" && <section className="panel"><div className="panel-heading"><div><h2>Equipe de planejamento<span className="count-label">{people.length}</span></h2><p>Perfis de demonstração. O diretório corporativo será gerenciado pelo Microsoft Entra ID.</p></div><ShieldCheck size={22} className="primary-text" /></div><div className="table-scroll"><table><thead><tr><th>COLABORADOR</th><th>E-MAIL</th><th>PERFIL</th><th>ATAS CRIADAS</th><th>ACESSO</th></tr></thead><tbody>{people.map(person => <tr key={person.email}><td><div className="person-cell"><Avatar name={person.name} /><strong>{person.name}</strong></div></td><td className="muted">{person.email}</td><td><span className="role-badge">{person.role}</span></td><td>{minutes.filter(minute => minute.dispatcher === person.name).length}</td><td><span className="badge badge-gray"><span />Demonstrativo</span></td></tr>)}</tbody></table></div></section>}

      {view === "integrations" && <><div className="notice"><ShieldCheck size={21} /><div><strong>Seu ecossistema, conectado com segurança.</strong><p>Integrações reais exigem consentimento do tenant, credenciais e implantação da API. Nenhuma conexão externa está ativa nesta demonstração.</p></div></div><div className="integrations-grid">{[{ name: "Microsoft Outlook", mark: "O", color: "outlook", text: "Distribuição das atas e anexos por e-mail corporativo." }, { name: "Microsoft Teams", mark: "T", color: "teams", text: "Publicação das atas nos canais da sua equipe." }, { name: "SharePoint & OneDrive", mark: "S", color: "sharepoint", text: "Documentos e links do seu ambiente de trabalho." }, { name: "Power BI", mark: "▥", color: "powerbi", text: "Indicadores de planejamento e operação em um só lugar." }, { name: "Azure Blob Storage", mark: "A", color: "azure", text: "Armazenamento centralizado de anexos e documentos." }, { name: "Azure OpenAI", mark: "✳", color: "openai", text: "Resumos executivos e identificação de riscos operacionais." }].map(item => <article className="integration-card" key={item.name}><div className="integration-card-top"><span className={`integration-logo ${item.color}`}>{item.mark}</span><span className="connection-status">Não configurado</span></div><h2>{item.name}</h2><p>{item.text}</p><Button variant="outline" onClick={() => setIntegration(item.name)}><Settings2 size={15} />Configurar integração <ArrowUpRight size={14} /></Button></article>)}</div></>}

      {view === "settings" && <div className="settings-layout"><section className="panel settings-panel"><div className="panel-heading"><div><h2>Preferências do workspace</h2><p>Personalize seu ambiente de planejamento.</p></div></div><form onSubmit={event => { event.preventDefault(); setSettingsSaved(true); notify("Preferências salvas neste dispositivo."); }}><label>Organização<input defaultValue="Vestas Brasil" disabled={role !== "Administrador"} required /></label><div className="form-grid"><label>Idioma<select defaultValue="pt-BR"><option value="pt-BR">Português (Brasil)</option><option disabled>English — em breve</option><option disabled>Español — em breve</option></select></label><label>Fuso horário<select><option>America/Sao_Paulo</option></select></label></div><div className="setting-row"><div><strong>Tema escuro</strong><p>Uma experiência confortável em qualquer horário.</p></div><button type="button" className={`toggle ${dark ? "on" : ""}`} role="switch" aria-checked={dark} aria-label="Tema escuro" onClick={() => setDark(!dark)}><span /></button></div><label>Perfil de demonstração<select value={role} onChange={event => setRole(event.target.value as Role)}><option>Administrador</option><option>Dispatcher</option><option>Leitor</option></select><small>Permissões locais para avaliação. A API valida os perfis no token corporativo.</small></label><Button type="submit"><Check size={16} />{settingsSaved ? "Preferências salvas" : "Salvar preferências"}</Button></form></section><section className="panel settings-panel"><div className="panel-heading"><div><h2>Segurança e dados</h2><p>Transparência sobre o seu ambiente.</p></div><ShieldCheck size={21} className="primary-text" /></div><div className="security-items"><div><span className="security-icon"><ShieldCheck size={19} /></span><div><strong>Microsoft Entra ID + MFA</strong><p>Preparado na API. Configuração do tenant necessária.</p></div></div><div><span className="security-icon"><Globe2 size={19} /></span><div><strong>Armazenamento de demonstração</strong><p>Dados e anexos são salvos somente neste navegador. Não utilize informações confidenciais.</p></div></div><div><span className="security-icon"><BookOpen size={19} /></span><div><strong>Histórico de versões</strong><p>Alterações registram versão, autor, data e ação.</p></div></div></div><Button variant="outline" onClick={() => { const blob = new Blob([JSON.stringify({ minutes, parks, exportedAt: new Date().toISOString() }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "wind-planner-backup.json"; anchor.click(); URL.revokeObjectURL(url); }}><Download size={16} />Exportar dados locais</Button></section></div>}
      <footer className="page-footer"><span>© 2026 Wind Planner <span className="middot">·</span> Vestas Brasil</span><span>One Standard. One Process. One Voice.</span><button onClick={() => setHelp(true)}>Central de ajuda <ArrowUpRight size={12} /></button></footer>
      {view === "dashboard" && <p className="demo-footnote">* Variações ilustrativas do protótipo. Totais e gráficos calculados sobre os registros locais.</p>}
      </motion.div></AnimatePresence>
    </main></div>
    {editor && <MinuteEditor minute={editor} parks={parks} readOnly={viewOnly || !editable} onClose={() => setEditor(null)} onSave={saveMinute} onSend={minute => { saveMinute(minute); requestEmail(minute); }} notify={notify} />}
    {parkEditor && <ParkEditor park={parkEditor} onClose={() => setParkEditor(null)} onSave={park => { setParks(previous => previous.some(item => item.id === park.id) ? previous.map(item => item.id === park.id ? park : item) : [...previous, park]); setParkEditor(null); notify("Parque salvo com sucesso."); }} />}
    <Modal open={!!emailMinute} onClose={() => setEmailMinute(null)} title="Pré-visualização do envio" subtitle="Demonstração · Nenhuma mensagem real será enviada.">{emailMinute && <div className="email-preview"><label>Destinatários<input type="text" placeholder="equipe@empresa.com, gestor@empresa.com" value={recipients} onChange={event => setRecipients(event.target.value)} />{emailError && <span className="field-error">{emailError}</span>}</label><label>Assunto<input readOnly value={`ATA DE PROGRAMAÇÃO SEMANAL - ${parks.find(park => park.id === emailMinute.parkId)?.name} - SEMANA ${emailMinute.week}`} /></label><div className="email-body"><p>Prezados,</p><p>Segue a ata da programação semanal do parque <strong>{parks.find(park => park.id === emailMinute.parkId)?.name}</strong>.</p><p>Favor verificar os pontos destacados e as ações pendentes.</p><p>Atenciosamente,<br /><strong>{emailMinute.dispatcher}</strong></p>{emailMinute.links.map(link => <a key={link.url} href={link.url} target="_blank" rel="noreferrer">{link.title}<ExternalLink size={12} /></a>)}</div><div className="email-attachment"><FileText size={20} /><span>Ata_S{emailMinute.week}.pdf<small>PDF corporativo + {emailMinute.attachments.length} anexo(s)</small></span><Button variant="ghost" size="icon" title="Gerar PDF" onClick={() => void exportPdf(emailMinute, parks.find(park => park.id === emailMinute.parkId))}><Download size={17} /></Button></div><div className="modal-footer"><Button variant="outline" onClick={() => setEmailMinute(null)}>Cancelar</Button><Button onClick={sendDemo}><Send size={16} />Simular envio</Button></div></div>}</Modal>
    <Modal open={!!deleteTarget} onClose={() => setDeleteTarget(null)} title={deleteTarget?.kind === "park" ? "Excluir parque?" : "Excluir ata?"} subtitle="Esta ação não pode ser desfeita no ambiente de demonstração."><div className="modal-body"><p>{deleteTarget?.kind === "park" ? "Parques com atas vinculadas não podem ser excluídos. Preserve o histórico da operação." : "O registro e seus anexos serão removidos deste navegador."}</p></div><div className="modal-footer"><Button variant="outline" onClick={() => setDeleteTarget(null)}>Cancelar</Button><Button variant="danger" onClick={() => { if (!deleteTarget) return; if (deleteTarget.kind === "park") { if (minutes.some(minute => minute.parkId === deleteTarget.id)) { notify("Este parque possui atas vinculadas e não pode ser excluído."); setDeleteTarget(null); return; } setParks(previous => previous.filter(park => park.id !== deleteTarget.id)); } else { setMinutes(previous => previous.filter(minute => minute.id !== deleteTarget.id)); } setDeleteTarget(null); notify("Registro excluído."); }}><Trash2 size={15} />Excluir registro</Button></div></Modal>
    <Modal open={help} onClose={() => setHelp(false)} title="Central de ajuda" subtitle="Wind Planner · One Standard. One Process. One Voice."><div className="help-content"><h3>Seu fluxo de programação</h3><ol><li>Cadastre os parques e responsáveis em Parques eólicos.</li><li>Crie uma ata com semana, participantes e conteúdo.</li><li>Revise os 13 itens do checklist e adicione anexos e links.</li><li>Salve uma versão ou abra a pré-visualização de envio.</li><li>Consulte o histórico, duplique atas e exporte o PDF.</li></ol><div className="notice"><CircleHelp size={20} /><p>Este protótipo usa dados fictícios e armazenamento local. O backend, a infraestrutura e os manuais de implantação estão incluídos no repositório. Integrações dependem de configuração corporativa.</p></div></div></Modal>
    <Modal open={!!integration} onClose={() => setIntegration(null)} title={`Configurar ${integration ?? "integração"}`} subtitle="Configuração realizada no backend e no Azure Key Vault."><div className="help-content"><p>Para habilitar esta integração no ambiente corporativo:</p><ol><li>Registre a aplicação no Microsoft Entra ID e conceda somente as permissões necessárias.</li><li>Configure as variáveis e segredos indicados no manual técnico.</li><li>Implante a API e valide as permissões no ambiente de homologação.</li></ol><div className="notice"><ShieldCheck size={20} /><p>Não informe tokens ou senhas no navegador. Nenhuma integração será marcada como conectada sem validação do serviço.</p></div><Button variant="outline" onClick={() => { setIntegration(null); navigate("settings"); }}><Settings2 size={16} />Ver configurações</Button></div></Modal>
    <AnimatePresence>{toast && <motion.div className="toast" role="status" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 10 }}><CheckCircle2 size={19} /><span>{toast}</span><button onClick={() => setToast("")} aria-label="Fechar aviso"><X size={15} /></button></motion.div>}</AnimatePresence>
  </div>;
}

function MinuteEditor({ minute, parks, readOnly, onClose, onSave, onSend, notify }: { minute: Minute | "new"; parks: Park[]; readOnly: boolean; onClose: () => void; onSave: (minute: Minute) => void; onSend: (minute: Minute) => void; notify: (message: string) => void }) {
  const isNew = minute === "new";
  const initial = isNew ? null : minute;
  const [tab, setTab] = useState("information");
  const [checklist, setChecklist] = useState(initial?.checklist ?? []);
  const [sections, setSections] = useState(initial?.sections ?? sectionLabels.map(title => ({ title, content: "" })));
  const [activeSection, setActiveSection] = useState(0);
  const [attachments, setAttachments] = useState<Attachment[]>(initial?.attachments ?? []);
  const [links, setLinks] = useState(initial?.links ?? []);
  const [linkTitle, setLinkTitle] = useState("");
  const [linkUrl, setLinkUrl] = useState("");
  const [blockName, setBlockName] = useState("");
  const [aiResult, setAiResult] = useState("");
  const [preview, setPreview] = useState<Attachment | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const { register, handleSubmit, formState: { errors } } = useForm<MinuteFields>({ resolver: zodResolver(minuteSchema), defaultValues: initial ?? { parkId: parks[0]?.id ?? "", week: 44, date: "2026-10-29", territory: "Nordeste", dispatcher: "Ana Martins", participants: "" } });
  const build = (fields: MinuteFields, status: Status): Minute => {
    const base: Minute = { ...fields, id: initial?.id ?? crypto.randomUUID(), checklist, sections, attachments, links, status, version: initial?.version ?? 0, audit: initial?.audit ?? [], sentAt: initial?.sentAt };
    return nextVersion(base, "Ana Martins", initial ? "Conteúdo, checklist e anexos revisados" : "Ata criada");
  };
  const submit = (send: boolean) => handleSubmit(fields => { const result = build(fields, send ? "Pendente" : "Rascunho"); if (send && !canSend(result)) { notify("Conclua todos os itens do checklist e preencha o conteúdo."); setTab("checklist"); return; } if (send) onSend(result); else onSave(result); }, () => { setTab("information"); notify("Revise os campos obrigatórios da ata."); })();
  const upload = async (files: FileList | null) => {
    if (!files) return;
    setUploading(true);
    try {
      for (const file of Array.from(files)) {
        if (!/\.(pdf|xlsx|csv|docx|pptx|png|jpe?g)$/i.test(file.name)) { notify(`Formato não permitido: ${file.name}`); continue; }
        if (file.size > 2 * 1024 * 1024) { notify("Na demonstração, o limite é 2 MB por arquivo."); continue; }
        const data = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); });
        setAttachments(previous => { const existing = previous.filter(item => item.name === file.name); return [...previous, { id: crypto.randomUUID(), name: file.name, size: file.size, type: file.type, data, version: Math.max(0, ...existing.map(item => item.version)) + 1 }]; });
      }
    } finally { setUploading(false); }
  };
  return <Modal open onClose={onClose} title={readOnly ? "Ata de programação semanal" : isNew ? "Nova ata de programação" : "Editar ata de programação"} subtitle={readOnly && initial ? `Semana ${initial.week} · ${initial.dispatcher} · Versão ${initial.version}` : "Um planejamento completo começa com um bom registro."} wide><div className="editor-tabs" role="tablist">{[{ id: "information", name: "Informações", icon: FileText }, { id: "checklist", name: `Checklist ${checklist.length}/13`, icon: CheckCheck }, { id: "content", name: "Conteúdo", icon: BookOpen }, { id: "attachments", name: `Anexos e links (${attachments.length + links.length})`, icon: Paperclip }, { id: "history", name: "Histórico", icon: Clock3 }].map(item => <button role="tab" aria-selected={tab === item.id} key={item.id} className={tab === item.id ? "active" : ""} onClick={() => setTab(item.id)}><item.icon size={15} />{item.name}</button>)}</div><div className="editor-body">
    {tab === "information" && <div className="form-grid editor-form"><label>Parque eólico *<select {...register("parkId")} disabled={readOnly}>{parks.map(park => <option key={park.id} value={park.id}>{park.name}</option>)}</select>{errors.parkId && <span className="field-error">{errors.parkId.message}</span>}</label><label>Território *<input {...register("territory")} disabled={readOnly} />{errors.territory && <span className="field-error">{errors.territory.message}</span>}</label><label>Semana *<input type="number" min="1" max="53" {...register("week", { valueAsNumber: true })} disabled={readOnly} />{errors.week && <span className="field-error">Semana entre 1 e 53</span>}</label><label>Data da reunião *<input type="date" {...register("date")} disabled={readOnly} />{errors.date && <span className="field-error">{errors.date.message}</span>}</label><label className="span-2">Dispatcher responsável *<input {...register("dispatcher")} disabled={readOnly} />{errors.dispatcher && <span className="field-error">{errors.dispatcher.message}</span>}</label><label className="span-2">Participantes *<textarea rows={5} placeholder={"Supervisor:\nLíder Técnico:\nStock Keeper:\nPlanejador:\nOutros participantes:"} {...register("participants")} disabled={readOnly} />{errors.participants && <span className="field-error">{errors.participants.message}</span>}<small>Inclua supervisor, líder técnico, stock keeper, planejador e demais participantes.</small></label></div>}
    {tab === "checklist" && <><div className="checklist-heading"><div><h3>Antes de compartilhar, confira.</h3><p>Todos os itens devem ser revisados para finalizar a ata.</p></div><span className="checklist-progress">{checklist.length} de 13</span></div><div className="progress-track"><span style={{ width: `${checklist.length / 13 * 100}%` }} /></div>{!readOnly && <Button variant="ghost" size="sm" onClick={() => setChecklist(checklist.length === 13 ? [] : [...checklistLabels])}><CheckCheck size={15} />{checklist.length === 13 ? "Desmarcar todos" : "Marcar todos como revisados"}</Button>}<div className="checklist-grid">{checklistLabels.map(label => <label key={label} className={checklist.includes(label) ? "checked" : ""}><input type="checkbox" checked={checklist.includes(label)} disabled={readOnly} onChange={() => setChecklist(previous => previous.includes(label) ? previous.filter(item => item !== label) : [...previous, label])} /><span>{label}</span></label>)}</div></>}
    {tab === "content" && <><div className="content-workspace"><div className="section-nav">{sections.map((section, index) => <button key={index} className={activeSection === index ? "active" : ""} onClick={() => setActiveSection(index)}><span className={stripHtml(section.content) ? "section-filled" : "section-empty"} />{section.title}</button>)}{!readOnly && <div className="new-section"><input value={blockName} onChange={event => setBlockName(event.target.value)} placeholder="Nome do novo bloco" aria-label="Nome do bloco personalizado" /><Button variant="outline" size="sm" onClick={() => { if (blockName.trim()) { setSections(previous => [...previous, { title: blockName.trim(), content: "" }]); setActiveSection(sections.length); setBlockName(""); } }}><Plus size={14} />Adicionar bloco</Button></div>}</div><div className="section-editor"><h3>{sections[activeSection]?.title}</h3><RichEditor key={activeSection} value={sections[activeSection]?.content ?? ""} readOnly={readOnly} onChange={content => setSections(previous => previous.map((section, index) => index === activeSection ? { ...section, content } : section))} /><div className="ai-toolbar"><span><Sparkles size={15} />Assistente de planejamento</span><Button variant="outline" size="sm" onClick={() => { const content = sections.map(section => stripHtml(section.content)).join(" "); const risks = [/(falta|indispon|ausên)/i.test(content) ? "Revisar disponibilidade de recursos e materiais." : null, /(vento|chuva|clim)/i.test(content) ? "Acompanhar janela climática e limites de vento para trabalho em altura." : null, /(sobrecarga|extra|capacity)/i.test(content) ? "Reavaliar a distribuição de capacidade da equipe." : null].filter(Boolean); setAiResult(`ANÁLISE LOCAL — Azure OpenAI não conectado\n\nResumo: ${content.slice(0, 450) || "Preencha o conteúdo para gerar um resumo."}\n\nPontos de atenção:\n${risks.length ? risks.map(risk => "• " + risk).join("\n") : "Nenhum padrão de risco identificado pela análise local. Valide o planejamento com a equipe."}`); }}><Sparkles size={13} />Resumo e riscos</Button></div>{aiResult && <pre className="ai-result">{aiResult}</pre>}</div></div></>}
    {tab === "attachments" && <div className="attachment-content"><h3>Documentos da programação</h3>{!readOnly && <button className="upload-zone" onClick={() => fileInput.current?.click()} disabled={uploading}>{uploading ? <Loader2 className="spin" size={27} /> : <Upload size={27} />}<strong>{uploading ? "Carregando..." : "Selecione arquivos para anexar"}</strong><span>PDF, XLSX, CSV, DOCX, PPTX, PNG ou JPG · até 2 MB no modo local</span></button>}<input type="file" multiple hidden ref={fileInput} accept=".pdf,.xlsx,.csv,.docx,.pptx,.png,.jpg,.jpeg" onChange={event => void upload(event.target.files)} /><div className="attachment-list">{attachments.map(file => <div key={file.id}><span className="file-tile"><Paperclip size={17} /></span><button className="attachment-name" onClick={() => setPreview(file)}>{file.name}<small>{(file.size / 1024).toFixed(0)} KB · versão {file.version}</small></button><a className="button button-ghost button-icon" href={file.data} download={file.name} title="Baixar anexo"><Download size={16} /></a>{!readOnly && <Button variant="ghost" size="icon" aria-label={`Remover ${file.name}`} onClick={() => setAttachments(previous => previous.filter(item => item.id !== file.id))}><Trash2 size={15} /></Button>}</div>)}</div><h3>Links relacionados</h3>{!readOnly && <div className="add-link"><input placeholder="Título do link" aria-label="Título do link" value={linkTitle} onChange={event => setLinkTitle(event.target.value)} /><input placeholder="https://..." aria-label="URL do link" value={linkUrl} onChange={event => setLinkUrl(event.target.value)} /><Button variant="outline" onClick={() => { const url = safeUrl(linkUrl); if (!url || !linkTitle.trim()) { notify("Informe um título e um endereço HTTP/HTTPS válido."); return; } setLinks(previous => [...previous, { title: linkTitle.trim(), url }]); setLinkTitle(""); setLinkUrl(""); }}><Plus size={16} />Adicionar</Button></div>}<div className="links-list">{links.map((link, index) => <div key={`${link.url}-${index}`}><Link2 size={17} /><a href={link.url} target="_blank" rel="noreferrer">{link.title}<small>{link.url}</small></a><ExternalLink size={14} />{!readOnly && <Button variant="ghost" size="icon" aria-label={`Remover link ${link.title}`} onClick={() => setLinks(previous => previous.filter((_, position) => position !== index))}><X size={15} /></Button>}</div>)}</div></div>}
    {tab === "history" && <div className="version-list"><div className="notice"><ShieldCheck size={20} /><p>Cada salvamento gera uma nova versão com autor, data e descrição da alteração. A demonstração registra eventos localmente; a API mantém snapshots completos.</p></div>{initial?.audit.slice().reverse().map((entry, index) => <div className="version-item" key={index}><span className="version-number">v{entry.version}</span><div><strong>{entry.action}</strong><p>{entry.actor} · {new Date(entry.date).toLocaleString("pt-BR")}</p></div><CheckCircle2 size={17} /></div>)}{!initial && <div className="empty-state"><Clock3 size={28} /><p>O histórico começa ao salvar a primeira versão.</p></div>}</div>}
    </div><div className="modal-footer editor-footer"><span><ShieldCheck size={14} />{readOnly ? `Versão ${initial?.version ?? 1} · Histórico rastreável` : "Alterações são registradas ao salvar"}</span><div><Button variant="outline" onClick={onClose}>{readOnly ? "Fechar" : "Cancelar"}</Button>{!readOnly && <><Button variant="outline" onClick={() => void submit(false)}><FileText size={15} />Salvar rascunho</Button><Button onClick={() => void submit(true)}><Send size={15} />Revisar e enviar</Button></>}{readOnly && initial && <Button onClick={() => void exportPdf(initial, parks.find(park => park.id === initial.parkId))}><Download size={15} />Exportar PDF</Button>}</div></div>
    <Modal open={!!preview} onClose={() => setPreview(null)} title={preview?.name ?? "Pré-visualização"} subtitle="Versão do anexo selecionado."><div className="attachment-preview">{preview?.type.startsWith("image/") ? <img src={preview.data} alt={preview.name} /> : preview?.type === "application/pdf" ? <iframe title={preview.name} src={preview.data} /> : <div className="empty-state"><FileText size={36} /><p>Este formato pode ser visualizado no aplicativo de origem.</p></div>}{preview && <a className="button button-primary" href={preview.data} download={preview.name}><Download size={16} />Baixar arquivo</a>}</div></Modal>
  </Modal>;
}

function ParkEditor({ park, onClose, onSave }: { park: Park | "new"; onClose: () => void; onSave: (park: Park) => void }) {
  const initial = park === "new" ? null : park;
  return <Modal open onClose={onClose} title={initial ? "Editar parque eólico" : "Novo parque eólico"} subtitle="Informações da operação e gestão responsável."><form onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); onSave({ id: initial?.id ?? crypto.randomUUID(), name: String(data.get("name")), client: String(data.get("client")), region: String(data.get("region")), state: String(data.get("state")), capacity: Number(data.get("capacity")), turbines: Number(data.get("turbines")), manager: String(data.get("manager")) }); }}><div className="modal-body form-grid"><label className="span-2">Nome do parque *<input name="name" required defaultValue={initial?.name} placeholder="Parque Eólico..." /></label><label>Cliente *<input name="client" required defaultValue={initial?.client} /></label><label>Região *<select name="region" defaultValue={initial?.region ?? "Nordeste"}><option>Nordeste</option><option>Sul</option><option>Sudeste</option><option>Norte</option><option>Centro-Oeste</option></select></label><label>Estado *<input name="state" pattern="[A-Za-z]{2}" maxLength={2} required defaultValue={initial?.state} placeholder="RN" /></label><label>Capacidade instalada (MW) *<input type="number" name="capacity" min="0.1" step="0.1" required defaultValue={initial?.capacity} /></label><label>Aerogeradores *<input type="number" name="turbines" min="1" required defaultValue={initial?.turbines} /></label><label>Gestor responsável *<input name="manager" required defaultValue={initial?.manager} /></label></div><div className="modal-footer"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><Button type="submit"><Check size={16} />Salvar parque</Button></div></form></Modal>;
}